function SidebarMenuButton({
  className,
  isActive = false,
  size = "default",
  tooltip,
  render,
  children,
  ...props
}: useRender.ComponentProps<"button"> &
  VariantProps<typeof sidebarMenuButtonVariants> & {
    isActive?: boolean
    tooltip?: string
  }) {
  const { state, isMobile, side } = useSidebar()
  const buttonSize = size === "sm" ? "sm" : size === "lg" ? "lg" : "default"
  const showTooltip = Boolean(tooltip) && state === "collapsed" && !isMobile

  if (showTooltip) {
    return (
      <Tooltip>
        <TooltipTrigger
          render={
            <SidebarMenuButtonPrimitive
              className={className}
              isActive={isActive}
              size={buttonSize}
              render={render}
              {...props}
            />
          }
        >
          {children}
        </TooltipTrigger>
        <TooltipContent side={side === "right" ? "left" : "right"}>
          {tooltip}
        </TooltipContent>
      </Tooltip>
    )
  }

  return (
    <SidebarMenuButtonPrimitive
      className={className}
      isActive={isActive}
      size={buttonSize}
      render={render}
      {...props}
    >
      {children}
    </SidebarMenuButtonPrimitive>
  )
}

