            key={toast.id}
            toast={toast}
            data-slot="toast"
            swipeDirection={["down", "right"]}
            className="rounded-2xl bg-popover text-popover-foreground ring-1 ring-foreground/5 select-none dark:ring-foreground/10 shadow-lg"
