import { cva, type VariantProps } from "class-variance-authority"
import * as React from "react"

import { cn } from "@/lib/utils"

import "./typography.css"

const typographyVariants = cva("w-full text-foreground", {
  variants: {
    variant: {
      article:
        "max-w-[65ch] [--type-size:0.875rem] [--type-leading:1.7] [--type-flow:1.25rem]",
      compact:
        "max-w-none [--type-size:0.8125rem] [--type-leading:1.55] [--type-flow:0.75rem]",
    },
  },
  defaultVariants: {
    variant: "article",
  },
})

function Typography({
  className,
  variant = "article",
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof typographyVariants>) {
  return (
    <div
      data-slot="typography"
      data-variant={variant}
      className={cn(typographyVariants({ variant }), className)}
      {...props}
    />
  )
}

export { Typography, typographyVariants }

@layer components {
  [data-slot="typography"] {
    font-size: var(--type-size, 0.875rem);
    line-height: var(--type-leading, 1.7);
    color: var(--foreground);

    > * {
      margin-block-start: var(--type-flow, 1.25rem);
    }

    > :first-child {
      margin-block-start: 0;
    }

    :where(h1, h2, h3, h4):not(:where(.not-typography, .not-typography *)) {
      font-weight: 500;
      letter-spacing: -0.025em;
      line-height: 1.25;
      color: var(--foreground);
    }

    :where(h1):not(:where(.not-typography, .not-typography *)) {
      font-size: 1.75em;
    }

    :where(h2):not(:where(.not-typography, .not-typography *)) {
      font-size: 1.4em;
    }

    :where(h3):not(:where(.not-typography, .not-typography *)) {
      font-size: 1.15em;
    }

    :where(h4):not(:where(.not-typography, .not-typography *)) {
      font-size: 1em;
    }

    :where(p):not(:where(.not-typography, .not-typography *)) {
      margin-block: 0;
      color: var(--muted-foreground);
    }

    :where(li):not(:where(.not-typography, .not-typography *)) {
      color: var(--muted-foreground);
    }

    :where(li + li):not(:where(.not-typography, .not-typography *)) {
      margin-block-start: 0.35em;
    }

    :where(strong):not(:where(.not-typography, .not-typography *)) {
      font-weight: 500;
      color: var(--foreground);
    }

    :where(a):not(:where(.not-typography, .not-typography *)) {
      color: var(--foreground);
      text-decoration-line: underline;
      text-underline-offset: 0.25rem;
    }

    :where(ul):not(:where(.not-typography, .not-typography *)) {
      list-style: disc;
      padding-inline-start: 1.25rem;
    }

    :where(ol):not(:where(.not-typography, .not-typography *)) {
      list-style: decimal;
      padding-inline-start: 1.25rem;
    }

    :where(blockquote):not(:where(.not-typography, .not-typography *)) {
      border-inline-start: 1px solid var(--border);
      padding-inline-start: 1rem;
      color: var(--muted-foreground);
    }

    :where(code):not(:where(.not-typography, .not-typography *)) {
      border-radius: calc(var(--radius) * 0.8);
      background: var(--muted);
      padding: 0.125rem 0.25rem;
      font-family: var(--font-jetbrains), ui-monospace, monospace;
      font-size: 0.85em;
    }

    :where(pre):not(:where(.not-typography, .not-typography *)) {
      overflow-x: auto;
      border-radius: calc(var(--radius) * 1.8);
      background: var(--muted);
      padding: 1rem;
      font-family: var(--font-jetbrains), ui-monospace, monospace;
      font-size: 0.85em;
      color: var(--foreground);
    }

    :where(pre code):not(:where(.not-typography, .not-typography *)) {
      background: transparent;
      padding: 0;
      font-size: inherit;
    }

    :where(hr):not(:where(.not-typography, .not-typography *)) {
      border: 0;
      border-top: 1px solid var(--border);
    }

    :where(table):not(:where(.not-typography, .not-typography *)) {
      width: 100%;
      border-collapse: collapse;
      text-align: start;
    }

    :where(th):not(:where(.not-typography, .not-typography *)) {
      border-bottom: 1px solid var(--border);
      padding: 0.5rem 0.75rem 0.5rem 0;
      text-align: start;
      font-size: 0.75rem;
      font-weight: 500;
      color: var(--muted-foreground);
    }

    :where(td):not(:where(.not-typography, .not-typography *)) {
      border-bottom: 1px solid var(--border);
      padding: 0.5rem 0.75rem 0.5rem 0;
      vertical-align: top;
      color: var(--muted-foreground);
    }
  }
}

